package com.bank.core;

import java.io.Serializable;
import java.math.BigDecimal;

public class Account implements Serializable {
    // Explicit, stable version id → controls deserialization compatibility.
    private static final long serialVersionUID = 1L;

    private String accountId;
    private BigDecimal balance;   // BigDecimal is Serializable
    private Owner owner;          // referenced object — serialized recursively
    private transient String sessionToken; // sensitive/runtime-only → excluded

    public Account(String accountId, BigDecimal balance, Owner owner, String sessionToken) {
        this.accountId = accountId;
        this.balance = balance;
        this.owner = owner;
        this.sessionToken = sessionToken;
    }

    public String getAccountId() { return accountId; }
    public BigDecimal getBalance() { return balance; }
    public Owner getOwner() { return owner; }
    public String getSessionToken() { return sessionToken; }
}
