package com.bank.core;

import java.io.*;
import java.math.BigDecimal;
import java.util.logging.*;

public class SerializationDemo {
    private static final Logger log = Logger.getLogger("BankLog");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws Exception {
        Owner rajesh = new Owner("Rajesh Kumar", "ABCDE1234F");
        Account account = new Account("SAV2001", new BigDecimal("1000000.00"),
                                      rajesh, "live-session-xyz");

        log.info(() -> "BEFORE: account=" + account.getAccountId()
                        + " balance=" + account.getBalance()
                        + " owner=" + account.getOwner().getName()
                        + " sessionToken=" + account.getSessionToken());

        // SERIALIZE the whole graph (Account → Owner) to bytes.
        byte[] bytes;
        try (ByteArrayOutputStream baos = new ByteArrayOutputStream();
             ObjectOutputStream oos = new ObjectOutputStream(baos)) {
            oos.writeObject(account); // writes Account AND its referenced Owner
            bytes = baos.toByteArray();
        }
        log.info(() -> "Serialized object graph into " + bytes.length + " bytes.");

        // DESERIALIZE — reconstruct the graph. No constructor is called.
        Account restored;
        try (ByteArrayInputStream bais = new ByteArrayInputStream(bytes);
             ObjectInputStream ois = new ObjectInputStream(bais)) {
            restored = (Account) ois.readObject();
        }

        log.info(() -> "AFTER: account=" + restored.getAccountId()
                        + " balance=" + restored.getBalance()
                        + " owner=" + restored.getOwner().getName()
                        + " (owner restored recursively)");
        log.warning(() -> "AFTER: sessionToken=" + restored.getSessionToken()
                           + " (null — transient, not serialized)");
        log.info("Serializable opt-in + matching serialVersionUID made this round trip work.");
    }
}
